191	export default function PipelinePage() {
192	  const router = useRouter();
193	  const [stages, setStages] = useState<Stage[]>([]);
194	  const [loading, setLoading] = useState(true);
195	  const [moving, setMoving] = useState<string | null>(null);
196	  const [draggedContactId, setDraggedContactId] = useState<string | null>(null);
197	  const [dragOverStageId, setDragOverStageId] = useState<string | null>(null);
198	
199	  const fetchPipeline = async () => {
200	    try {
201	      const res = await fetch("/api/pipeline");
202	      const data = await res.json();
203	      setStages(Array.isArray(data) ? data : []);
204	    } catch (err) {
205	      console.error(err);
206	    } finally {
207	      setLoading(false);
208	    }
209	  };
210	
211	  useEffect(() => { fetchPipeline(); }, []);
212	
213	  const moveContact = async (contactId: string, stageId: string | null) => {
214	    // Optimistic update
215	    setStages((prev) => {
216	      const contact = prev.flatMap((s) => s.contacts).find((c) => c.id === contactId);
217	      if (!contact) return prev;
218	      return prev.map((s) => ({
219	        ...s,
220	        contacts: s.id === stageId
221	          ? [...s.contacts.filter((c) => c.id !== contactId), contact]
222	          : s.contacts.filter((c) => c.id !== contactId),
223	      }));
224	    });
225	
226	    setMoving(contactId);
227	    try {
228	      await fetch("/api/pipeline", {
229	        method: "PATCH",
230	        headers: { "Content-Type": "application/json" },
231	        body: JSON.stringify({ contactId, stageId }),
232	      });
233	    } catch (err) {
234	      console.error(err);
235	      fetchPipeline(); // revert on error
236	    } finally {
237	      setMoving(null);
238	    }
239	  };
240	
241	  const addStage = async (name: string, color: string) => {
242	    const res = await fetch("/api/pipeline", {
243	      method: "POST",
244	      headers: { "Content-Type": "application/json" },
245	      body: JSON.stringify({ name, color }),
246	    });
247	    if (res.ok) {
248	      const stage = await res.json();
249	      setStages((prev) => [...prev, { ...stage, contacts: [] }]);
250	    }
251	  };
252	
253	  const renameStage = async (id: string, name: string, color: string) => {
254	    setStages((prev) => prev.map((s) => s.id === id ? { ...s, name, color } : s));
255	    await fetch("/api/pipeline", {
256	      method: "PUT",
257	      headers: { "Content-Type": "application/json" },
258	      body: JSON.stringify({ id, name, color }),
259	    });
260	  };
261	
262	  const deleteStage = async (id: string) => {
263	    if (!confirm("Hapus stage ini? Semua contact di dalamnya akan dilepaskan dari pipeline.")) return;
264	    setStages((prev) => prev.filter((s) => s.id !== id));
265	    await fetch(`/api/pipeline?id=${id}`, { method: "DELETE" });
266	  };
267	
268	  const handleDragStart = (e: React.DragEvent, contactId: string) => {
269	    setDraggedContactId(contactId);
270	    e.dataTransfer.setData("contactId", contactId);
271	    e.dataTransfer.effectAllowed = "move";
272	  };
273	
274	  const handleDragOver = (e: React.DragEvent, stageId: string) => {
275	    e.preventDefault();
276	    e.dataTransfer.dropEffect = "move";
277	    setDragOverStageId(stageId);
278	  };
279	
280	  const handleDrop = async (e: React.DragEvent, stageId: string) => {
